pub struct Tester {
    handle: Handle,
    n: usize,

    ctrler_addrs: Vec<SocketAddr>,
    _ctrlers: Vec<Arc<ShardCtrler>>,
    ctrler_ck: CtrlerClerk,

    groups: Vec<Group>,

    max_raft_state: Option<usize>,

    // begin()/end() statistics
    t0: Instant,
}

struct Group {
    gid: u64,
    addrs: Vec<SocketAddr>,
    servers: Mutex<Vec<Option<Arc<ShardKvServer>>>>,
}

impl Tester {
    pub async fn new(n: usize, unreliable: bool, max_raft_state: Option<usize>) -> Tester {
        let handle = Handle::current();
        if unreliable {
            NetSim::current().update_config(|cfg| {
                cfg.packet_loss_rate = 0.1;
                cfg.send_latency = Duration::from_millis(1)..Duration::from_millis(27);
            });
        }

        let n_ctrler = 3;
        let ctrler_addrs = (0..n_ctrler)
            .map(|i| SocketAddr::from(([0, 0, 1, i as _], 1)))
            .collect::<Vec<_>>();
        let mut ctrlers = vec![];
        for i in 0..n_ctrler {
            create_node(&handle, ctrler_addrs[i]);
            let handle = start_node(&handle, ctrler_addrs[i]);
            let ctrler = handle
                .spawn(ShardCtrler::new(ctrler_addrs.clone(), i, max_raft_state))
                .await.unwrap();
            ctrlers.push(ctrler);
        }
        let ctrler_ck = CtrlerClerk::new(ctrler_addrs.clone());

        let n_groups: usize = 3;
        let groups: Vec<Group> = (0..n_groups)
            .map(|i| Group {
                gid: i as u64 + 100,
                addrs: (0..n)
                    .map(|j| SocketAddr::from(([0, 1, i as _, j as _], 1)))
                    .collect(),
                servers: Mutex::new(vec![None; n]),
            })
            .collect();

        for group in &groups {
            for &addr in &group.addrs { create_node(&handle, addr); }
        }

        let tester = Tester {
            handle,
            n,
            ctrler_addrs,
            _ctrlers: ctrlers,
            ctrler_ck,
            groups,
            max_raft_state,
            t0: Instant::now(),
        };
        for g in 0..n_groups {
            for i in 0..n {
                tester.start_server(g, i).await;
            }
        }
        tester
    }

    /// check that no server's log is too big.
    pub fn check_logs(&self) {
        for group in self.groups.iter() {
            for &addr in group.addrs.iter() {
                let state_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "state").unwrap_or(0);
                let snap_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "snapshot").unwrap_or(0);
                if let Some(limit) = self.max_raft_state {
                    assert!(
                        state_size as usize <= 8 * limit,
                        "raft state size {} exceed limit {}",
                        state_size,
                        limit
                    );
                } else {
                    assert_eq!(
                        snap_size, 0,
                        "max_raft_state is None, but snapshot is non-empty!"
                    );
                }
            }
        }
    }

    pub fn total_size(&self) -> u64 {
        let mut size = 0;
        for group in self.groups.iter() {
            for &addr in group.addrs.iter() {
                let state_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "state").unwrap();
                let snap_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "snapshot").unwrap();
                size += state_size + snap_size;
            }
        }
        size
    }

    fn rpc_total(&self) -> u64 {
        NetSim::current().stat().msg_count / 2
    }

    // Create a clerk with clerk specific server names.
    // Give it connections to all of the servers
    pub fn make_client(&self) -> Clerk {
        Clerk::new(self.ctrler_addrs.clone())
    }

    /// Start i'th server of group.
    pub async fn start_server(&self, group: usize, i: usize) {
        debug!("start_server({}, {})", group, i);
        let group = &self.groups[group];
        let addrs = group.addrs.clone();
        let handle = start_node(&self.handle, group.addrs[i]);
        let ctrl_ck = CtrlerClerk::new(self.ctrler_addrs.clone());
        let kv = handle
            .spawn(ShardKvServer::new(
                ctrl_ck,
                addrs,
                group.gid,
                i,
                self.max_raft_state,
            ))
            .await.unwrap();
        group.servers.lock().unwrap()[i] = Some(kv);
    }

    /// Shutdown i'th server of group.
    pub fn shutdown_server(&self, group: usize, i: usize) {
        debug!("shutdown_server({}, {})", group, i);
        let group = &self.groups[group];
        kill(&self.handle, group.addrs[i]);
        group.servers.lock().unwrap()[i] = None;
    }

    pub async fn start_group(&self, group: usize) {
        for i in 0..self.n {
            self.start_server(group, i).await;
        }
    }

    pub fn shutdown_group(&self, group: usize) {
        for i in 0..self.n {
            self.shutdown_server(group, i);
        }
    }

    // tell the shardctrler that a group is joining.
    pub async fn join(&self, group: usize) {
        self.joins(&[group]).await;
    }

    pub async fn joins(&self, groups: &[usize]) {
        debug!("join({:?})", groups);
        let mut m = HashMap::new();
        for &g in groups {
            let gid = self.groups[g].gid;
            let names = self.groups[g].addrs.clone();
            m.insert(gid, names);
        }
        self.ctrler_ck.join(m).await;
    }

    // tell the shardctrler that a group is leaving.
    pub async fn leave(&self, group: usize) {
        self.leaves(&[group]).await;
    }

    pub async fn leaves(&self, groups: &[usize]) {
        debug!("leave({:?})", groups);
        let gids: Vec<u64> = groups.iter().map(|&g| self.groups[g].gid).collect();
        self.ctrler_ck.leave(&gids).await;
    }

    /// QUERY to find shards now owned by group
    pub async fn query_shards_of(&self, group: usize) -> HashSet<usize> {
        let c = self.ctrler_ck.query().await;
        let gid = self.groups[group].gid;
        (0..N_SHARDS).filter(|&i| c.shards[i] == gid).collect()
    }

    /// End a Test -- the fact that we got here means there
    /// was no failure.
    /// print the Passed message,
    /// and some performance numbers.
    pub fn end(&self) {
        self.check_timeout();

        // real time
        let t = self.t0.elapsed();
        // number of Raft peers
        let npeers = self.n;
        // number of RPC sends
        let nrpc = self.rpc_total();

        info!("  ... Passed --");
        info!("  {:?}  {} {}", t, npeers, nrpc);
    }

    fn check_timeout(&self) {
        // enforce a two minute real-time limit on each test
        if self.t0.elapsed() > Duration::from_secs(120) {
            panic!("test took longer than 120 seconds");
        }
    }
}

async fn challenge1_delete_4b() {
    info!("Test: shard deletion (challenge 1) ...");

    // "1" means force snapshot after every log entry.
    let t = Tester::new(3, false, Some(1)).await;
    let ck = t.make_client();

    t.join(0).await;

    // 30,000 bytes of total values.
    let n = 30;
    let kvs = (0..n)
        .map(|i| (i.to_string(), rand_string(1000)))
        .collect::<Vec<_>>();
    ck.put_kvs(&kvs).await;
    ck.check_kvs(&kvs[..3]).await;

    for _iters in 0..2 {
        t.join(1).await;
        t.leave(0).await;
        t.join(2).await;

        time::sleep(Duration::from_secs(3)).await;
        ck.check_kvs(&kvs[..3]).await;
        t.leave(1).await;
        t.join(0).await;
        t.leave(2).await;

        time::sleep(Duration::from_secs(3)).await;
        ck.check_kvs(&kvs[..3]).await;
    }

    t.join(1).await;
    t.join(2).await;
    for _ in 0..3 {
        time::sleep(Duration::from_secs(1)).await;
        ck.check_kvs(&kvs[..3]).await;
    }

    let total = t.total_size();
    // 27 keys should be stored once.
    // 3 keys should also be stored in client dup tables.
    // everything on 3 replicas.
    // plus slop.
    let expected = 3 * (((n - 3) * 1000) + 2 * 3 * 1000 + 6000);
    assert!(
        total <= expected,
        "snapshot + persisted Raft state are too big: {} > {}",
        total,
        expected
    );

    ck.check_kvs(&kvs).await;

    t.end();
}

/// optional test to see whether servers can handle
/// shards that are not affected by a config change
/// while the config change is underway
#[madsim::test]
async fn challenge2_unaffected_4b() {
    info!("Test: unaffected shard access (challenge 2) ...");

    let t = Tester::new(3, true, Some(100)).await;
    let ck = t.make_client();

    // JOIN 100
    t.join(0).await;

    // Do a bunch of puts to keys in all shards
    let n = 10;
    let mut kvs = (0..n)
        .map(|i| (i.to_string(), "100".into()))
        .collect::<Vec<_>>();
    ck.put_kvs(&kvs).await;

    // JOIN 101
    t.join(1).await;

    // QUERY to find shards now owned by 101
    let owned = t.query_shards_of(1).await;

    // Wait for migration to new config to complete, and for clients to
    // start using this updated config. Gets to any key k such that
    // owned[shard(k)] == true should now be served by group 101.
    time::sleep(Duration::from_secs(1)).await;
    for (k, v) in kvs.iter_mut() {
        let shard = super::key2shard(k);
        if owned.contains(&shard) {
            *v = "101".into();
            ck.put(k.clone(), "101".into()).await;
        }
    }

    // KILL 100
    t.shutdown_group(0);

    // LEAVE 100
    // 101 doesn't get a chance to migrate things previously owned by 100
    t.leave(0).await;

    // Wait to make sure clients see new config
    time::sleep(Duration::from_secs(1)).await;

    // And finally: check that gets/puts for 101-owned keys still complete
    for (k, v) in kvs.iter() {
        let shard = super::key2shard(k);
        if owned.contains(&shard) {
            ck.check(k.clone(), v.clone()).await;
            ck.put(k.clone(), v.clone() + "-1").await;
            ck.check(k.clone(), v.clone() + "-1").await;
        }
    }

    t.end();
}

/// optional test to see whether servers can handle operations on shards that
/// have been received as a part of a config migration when the entire migration
/// has not yet completed.
#[madsim::test]
async fn challenge2_partial_4b() {
    info!("Test: partial migration shard access (challenge 2) ...");

    let t = Tester::new(3, true, Some(100)).await;
    let ck = t.make_client();

    // JOIN 100 + 101 + 102
    t.joins(&[0, 1, 2]).await;

    // Give the implementation some time to reconfigure
    time::sleep(Duration::from_secs(1)).await;

    // Do a bunch of puts to keys in all shards
    let n = 10;
    let kvs = (0..n)
        .map(|i| (i.to_string(), "100".into()))
        .collect::<Vec<_>>();
    ck.put_kvs(&kvs).await;

    // QUERY to find shards now owned by 102
    let owned = t.query_shards_of(2).await;

    // KILL 100
    t.shutdown_group(0);

    // LEAVE 100 + 102
    // 101 can get old shards from 102, but not from 100. 101 should start
    // serving shards that used to belong to 102 as soon as possible
    t.leaves(&[0, 2]).await;

    // Give the implementation some time to start reconfiguration
    // And to migrate 102 -> 101
    time::sleep(Duration::from_secs(1)).await;

    // And finally: check that gets/puts for 101-owned keys now complete
    for (k, v) in kvs.iter() {
        let shard = super::key2shard(k);
        if owned.contains(&shard) {
            ck.check(k.clone(), v.clone()).await;
            ck.put(k.clone(), v.clone() + "-2").await;
            ck.check(k.clone(), v.clone() + "-2").await;
        }
    }

    t.end();
}
